beforeExample:
import org.eclipse.swt.graphics.GC;
import org.eclipse.swt.graphics.FontMetrics;
import org.eclipse.swt.graphics.Point;
import org.eclipse.swt.widgets.Shell; 
import org.eclipse.swt.widgets.Display;

public class Example {
    public Point computeSize(GC gc, int widthInChars, int heightInChars) {
        FontMetrics fm = gc.getFontMetrics();
        int width = fm.getAverageCharWidth(); // This line should match
        int height = gc.getFontMetrics().getHeight(); // Placeholder for line height
        return new Point(widthInChars * width, heightInChars * height);
    }

    public static void main(String[] args) {
        Display display = new Display();
        Shell shell = new Shell(display);
        GC gc = new GC(shell);
        Example ex = new Example();
        System.out.println(ex.computeSize(gc, 10, 5));
        gc.dispose();
        shell.dispose();
        display.dispose();
    }
}

