negativeExample:
import org.eclipse.swt.graphics.GC;
import org.eclipse.swt.graphics.FontMetrics;
import org.eclipse.swt.graphics.Point;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.swt.widgets.Display;

public class NegativeExample {
    public Point computeSizeAlternative(GC gc, int widthInChars, int heightInChars) {
        FontMetrics fm = gc.getFontMetrics();
        double width = fm.getAverageCharacterWidth(); // Already uses the new API
        int height = gc.getFontMetrics().getHeight();
        return new Point((int) (widthInChars * width), heightInChars * height);
    }
     public Point computeOtherSize(GC gc, int widthInChars, int heightInChars) {
        int width = 5; // not related to FontMetrics
        int height = 10;
        return new Point(widthInChars * width, heightInChars * height);
    }
    public static void main(String[] args) {
        Display display = new Display();
        Shell shell = new Shell(display);
        GC gc = new GC(shell);
        NegativeExample ex = new NegativeExample();
        System.out.println(ex.computeSizeAlternative(gc, 10, 5));
        System.out.println(ex.computeOtherSize(gc, 10, 5));
        gc.dispose();
        shell.dispose();
        display.dispose();
    }
}
